const listGitMaterials = `-- name: ListGitMaterials :many
SELECT id, workspace_id, project_id, title, path, version, status, blocker, current_revision_id, baseline, created_at, updated_at FROM git_material WHERE workspace_id=$1 AND project_id=$2 ORDER BY created_at DESC,id
`

type ListGitMaterialsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	ProjectID   pgtype.UUID `json:"project_id"`
}

func (q *Queries) ListGitMaterials(ctx context.Context, arg ListGitMaterialsParams) ([]GitMaterial, error) {
	rows, err := q.db.Query(ctx, listGitMaterials, arg.WorkspaceID, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GitMaterial{}
	for rows.Next() {
		var i GitMaterial
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProjectID,
			&i.Title,
			&i.Path,
			&i.Version,
			&i.Status,
			&i.Blocker,
			&i.CurrentRevisionID,
			&i.Baseline,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

